from decimal import Decimal
from typing import Any


def _field(source: dict | None, name: str) -> Any:
    if not source:
        return ""
    value = source.get(name, "")
    return "" if value is None else value


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _date_ge(left: Any, right: Any) -> bool:
    left = "" if left is None else left
    right = "" if right is None else right
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []
    previous = old if event == "UPDATE" and old is not None else {}

    def failure(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    status = _field(record, "STAT_CD")
    amount = _nvl(_field(record, "AMT"), 0)
    close_date = _field(record, "CLOSE_DT")
    lost_reason = _field(record, "LOST_RSN")
    stage_pct = _number(_field(record, "STAGE_PCT"))

    # OPP-001
    if not (_number(amount) >= Decimal("0")):
        failure("E3001", "Amount negative")

    # OPP-002
    if not (not (status == "W" and _number(amount) == Decimal("0"))):
        failure("E3002", "Won opportunity requires amount")

    # OPP-003
    if not (not (status == "L" and lost_reason == "")):
        failure("E3003", "Lost reason required")

    # OPP-004
    if not (not (status == "W" and close_date == "00000000")):
        failure("E3004", "Won opportunity requires close date")

    # OPP-005
    if event in ("UPDATE",):
        old_status = _field(previous, "STAT_CD")
        if not (not (old_status == "W" and status != "W")):
            failure("E3005", "Cannot reopen a won opportunity")

    # OPP-006
    stage_consistent = (
        (status == "P" and stage_pct == Decimal("10"))
        or (status == "Q" and stage_pct == Decimal("25"))
        or (status == "N" and stage_pct == Decimal("60"))
        or (status == "W" and stage_pct == Decimal("100"))
        or (status == "L" and stage_pct == Decimal("0"))
    )
    if not stage_consistent:
        failure("E3006", "Stage percent inconsistent with status")

    # OPP-007
    if event in ("INSERT",):
        if not (close_date == "00000000" or _date_ge(close_date, today)):
            failure("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
